import { CallExpressionShape, type Record, type Shape, VariableStatementShape } from './shape'
import type { Diagnostics } from './context'

/**
 * `sys_*` fields that are always written by the generic record-to-XML pipeline
 * (see `RecordPlugin.toFile` / `unloadBuilder`) outside of `record.entries()`. Letting
 * `$override` inject these would produce duplicate/conflicting XML elements (e.g. a second
 * `<sys_id>`) or corrupt the record's identity/scope/file path, so these stay blocked
 * regardless of table. Every other `sys_*` field is allowed through by default.
 */
const SYS_FIELD_OVERRIDE_BLOCKLIST: ReadonlySet<string> = new Set([
    'sys_id',
    'sys_scope',
    'sys_update_name',
    'sys_domainpath',
])

/**
 * Injects `$override` properties from the Fluent shape into the record, so plugins don't
 * need to explicitly map them. Only injects fields not already set by the plugin.
 */
export function mergeOverrideFromShape(shape: Shape, record: Record, diagnostics: Diagnostics): Record {
    if (!(shape instanceof CallExpressionShape)) {
        return record
    }
    const override = shape.getArgument(0).ifObject()?.get('$override').ifObject()
    if (!override) {
        return record
    }

    const extra: { [key: string]: Shape } = {}
    const overrideKeys = new Set<string>()
    for (const [key, value] of override.entries()) {
        if (SYS_FIELD_OVERRIDE_BLOCKLIST.has(key)) {
            diagnostics.error(
                value,
                `$override: '${key}' is managed by the framework and cannot be overridden — remove it or use a supported API property instead.`
            )
            continue
        }
        if (record.get(key).isDefined()) {
            diagnostics.warn(
                value,
                `$override: '${key}' is already set by the plugin and will be ignored — use the corresponding API property instead.`
            )
            continue
        }
        overrideKeys.add(key)
        extra[key] = value
    }

    const result = overrideKeys.size > 0 ? record.merge(extra) : record
    return result.withOverrideKeys(overrideKeys)
}

/** The sys_id of the seeded "global" domain — the default when no domain separation is in effect. */
const DEFAULT_SYS_DOMAIN_VALUE = 'global'

/**
 * Injects `$override` into the shape. Includes:
 * - Custom fields (`u_*` / `x_*`) with non-empty values.
 * - `sys_domain` whenever it's set to a non-default domain, even on a record with no prior
 *   `$override` — this is how a first-time transform surfaces an existing domain assignment.
 * - Any other field (including other `sys_*` fields not in `SYS_FIELD_OVERRIDE_BLOCKLIST`) that
 *   was explicitly in the existing record's `$override` — re-emitted with the fresh DB value.
 */
export function mergeOverrideFromRecord(
    record: Record,
    shape: Shape,
    accessed: Set<string>,
    existingRecord?: Record
): Shape {
    const inner = shape instanceof VariableStatementShape ? shape.getInitializer() : shape
    const ce = inner instanceof CallExpressionShape ? inner : null
    if (!ce) {
        return shape
    }

    const firstArg = ce.getArgument(0).ifObject()
    if (!firstArg || firstArg.get('$override').isDefined()) {
        return shape
    }

    const existingOverrideKeys = existingRecord?.getOverrideKeys()
    const override: globalThis.Record<string, Shape> = {}
    for (const [key, value] of record.entries()) {
        if (SYS_FIELD_OVERRIDE_BLOCKLIST.has(key) || accessed.has(key)) {
            continue
        }
        const isTrackedField = key.startsWith('u_') || key.startsWith('x_') || key === 'sys_domain'
        if (!isTrackedField && !existingOverrideKeys?.has(key)) {
            continue
        }
        // Preserve empty strings when the key was explicitly put in $override previously —
        // that's how users clear a field. Only skip empty strings for newly-discovered fields.
        const wasExplicitlyOverridden = existingOverrideKeys?.has(key)
        if (!value.isDefined() || (!wasExplicitlyOverridden && value.ifString()?.isEmpty())) {
            continue
        }
        // Don't clutter every generated file with the default domain — only surface sys_domain
        // when it's non-default, or was already explicitly tracked in $override.
        if (
            !wasExplicitlyOverridden &&
            key === 'sys_domain' &&
            value.ifString()?.getValue() === DEFAULT_SYS_DOMAIN_VALUE
        ) {
            continue
        }
        override[key] = value
    }

    if (Object.keys(override).length === 0) {
        return shape
    }

    const modified = new CallExpressionShape({
        source: ce.getSource(),
        callee: ce.getCallee(),
        args: [firstArg.merge({ $override: override }), ...ce.getArguments().slice(1)],
        exportName: ce.getExportName(),
    })

    if (!(shape instanceof VariableStatementShape)) {
        return modified
    }
    return new VariableStatementShape({
        source: shape.getSource(),
        variableName: shape.getVariableName(),
        initializer: modified,
        isExported: shape.isExported(),
    })
}
